"""Regenerate settings documentation and acceptance tables from saved records.

No inference and no hand-entered empirical counts: SQLite/JSON/JUnit are inputs.
"""
import json
from pathlib import Path
import xml.etree.ElementTree as ET

from auto_eureka_scientist.settings import schema


ROOT=Path(__file__).resolve().parents[1]


def generate():
    contract=schema()
    (ROOT/'docs/settings.schema.json').write_text(json.dumps(contract,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    rows=['# Settings reference','',
        'Generated by `uv run python scripts/console_reference.py` from the same registry used by configuration validation, CLI overrides, and browser forms. See [console controls](console.md) for precedence and recovery semantics. Credentials are not registered settings.','',
        'Defaults below are field defaults. Backend defaults resolve an empty model to `haiku` or `gpt-6-luna`; digits profiles retain their historical bounded allowances. The console starts with one completed loop and ordered selection; legacy `mode=cycle` also stops after one completed cycle.','',
        '| Setting | Default | Type / allowed values | Units | Applies | Scope / backend | Description |',
        '|---|---|---|---|---|---|---|']
    for key,definition in contract['properties'].items():
        default=json.dumps(definition.get('default','required'),ensure_ascii=False)
        allowed=json.dumps(definition.get('enum',definition['type']),ensure_ascii=False)
        values=[f'`{key}`',f'`{default}`',allowed,definition['x-units'],definition['x-apply'],
            definition['x-scope']+' / '+', '.join(definition['x-backends']),definition['description']]
        rows.append('| '+' | '.join(str(v).replace('|','\\|') for v in values)+' |')
    (ROOT/'docs/settings.md').write_text('\n'.join(rows)+'\n',encoding='utf-8')
    records=ROOT/'reports/console-acceptance.json'
    report=['# Console acceptance evidence','',
        'Generated from saved offline test and live smoke records. These are engineering checks, not estimates of scientific competence. Fake CLIs create explicit fixture artifacts; they do not train or invoke provider models.','']
    junit=ROOT/'reports/console-tests.xml'
    if junit.exists():
        suites=list(ET.parse(junit).getroot().iter('testsuite'))
        report+=['| Suite | Tests | Failures | Errors | Skipped |','|---|---:|---:|---:|---:|']
        for suite in suites:
            report.append('| '+' | '.join(suite.get(k,'0') for k in ('name','tests','failures','errors','skipped'))+' |')
        report+=['','The saved JUnit file includes individual cases and execution times.','']
    if records.exists():
        data=json.loads(records.read_text(encoding='utf-8'))
        report+=['| Check | Recorded outcome |','|---|---|']
        for check in data.get('browser',[]): report.append('| '+check['check']+' | '+check['outcome']+' |')
        report+=['','| Live model | Status | Calls | Phase before / after | Reported identity |','|---|---|---:|---|---|']
        for check in data.get('live',[]):
            report.append(f'| {check["model"]} | {check["status"]} | {check["calls"]} | {check["phase_before"]} / {check["phase_after"]} | {", ".join(check.get("reported_models",[])) or "Not exposed"} |')
        for check in data.get('live',[]):
            for warning in check.get('warnings',[]):report+=['',f'{check["model"]}: {warning}']
    report+=['','[Implementation issues, corrections and limitations](console-learnings.md) describe the observed failures without replacing earlier observations.','']
    report+=['','Live checks follow [the prospective console addendum](console-validation-preregistration.md). No earlier Sonnet or Sol result is relabeled as validation of this interface. Prior scientific findings remain unchanged.','',
        'Known limits: telemetry depends on host access and provider reporting; process CPU samples need more than one observation. A hard crash can lose up to one configured heartbeat interval of active-time accounting. External publication services can fail and need recovery. The console is a local operator interface, not an authentication boundary for a hostile local user.','']
    (ROOT/'reports/console-acceptance.md').write_text('\n'.join(report),encoding='utf-8')


if __name__=='__main__': generate()
